import React from 'react';
import { useCurrentFrame, useVideoConfig } from 'remotion';

/**
 * ReLaunch Studio — Kinetic Word-Highlight Subtitle Component
 * Emulates the viral TikTok / Instagram Reels captions aesthetic.
 * Reads word timestamps generated by faster-whisper.
 */

export interface WordTimestamp {
  word: string;
  start: number; // in seconds
  end: number;   // in seconds
}

interface CaptionsProps {
  words: WordTimestamp[];
  highlightColor?: string;
  textColor?: string;
  maxWordsPerSegment?: number;
}

export const Captions: React.FC<CaptionsProps> = ({
  words = [],
  highlightColor = '#FFE600', // TikTok bright yellow
  textColor = '#FFFFFF',
  maxWordsPerSegment = 4,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const currentTime = frame / fps;

  if (!words || words.length === 0) {
    return null;
  }

  // Find index of currently spoken word
  const activeWordIndex = words.findIndex(
    (w) => currentTime >= w.start && currentTime <= w.end
  );

  // Fallback to closest preceding word if in micro-pause
  let displayIndex = activeWordIndex;
  if (displayIndex === -1) {
    displayIndex = words.findLastIndex((w) => currentTime >= w.end);
  }

  if (displayIndex === -1) {
    return null;
  }

  // Calculate segment window around active word
  const segmentStartIndex =
    Math.floor(displayIndex / maxWordsPerSegment) * maxWordsPerSegment;
  const currentSegment = words.slice(
    segmentStartIndex,
    segmentStartIndex + maxWordsPerSegment
  );

  return (
    <div
      style={{
        position: 'absolute',
        bottom: 240, // Positioned in lower-third, above native UI controls
        left: 0,
        right: 0,
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        pointerEvents: 'none',
        zIndex: 9000,
      }}
    >
      <div
        style={{
          display: 'flex',
          flexWrap: 'wrap',
          justifyContent: 'center',
          gap: 12,
          maxWidth: '85%',
          textAlign: 'center',
        }}
      >
        {currentSegment.map((w, idx) => {
          const globalIdx = segmentStartIndex + idx;
          const isHighlighted = globalIdx === activeWordIndex;

          return (
            <span
              key={`${w.word}-${globalIdx}`}
              style={{
                fontFamily: "'Montserrat', -apple-system, sans-serif",
                fontSize: 48,
                fontWeight: 900,
                textTransform: 'uppercase',
                color: isHighlighted ? highlightColor : textColor,
                textShadow:
                  '0 3px 6px rgba(0,0,0,0.9), 0 0 20px rgba(0,0,0,0.8), -2px -2px 0 #000, 2px -2px 0 #000, -2px 2px 0 #000, 2px 2px 0 #000',
                transform: isHighlighted ? 'scale(1.08)' : 'scale(1.0)',
                transition: 'transform 0.08s ease, color 0.08s ease',
                display: 'inline-block',
                letterSpacing: '-0.5px',
              }}
            >
              {w.word}
            </span>
          );
        })}
      </div>
    </div>
  );
};
